/**
 * @indigodb/generator
 *
 * Takes a parsed IndigoDB Schema AST and generates TypeScript/JavaScript
 * client code with full type safety.
 */

import type { Schema, Model, Field, FieldType } from "@indigodb/ast";
import { ScalarType } from "@indigodb/ast";

// Runtime client generator (typed IndigoClient bound to @indigodb/client).
export { generateClient } from "./client.js";

// ─── Generator Options ───────────────────────────────────────────────────────

export interface GeneratorOptions {
  /** Output directory for generated files. */
  output?: string;
  /** Whether to generate runtime client or just types. */
  mode?: "client" | "types-only";
}

// ─── Scalar Type Mapping ─────────────────────────────────────────────────────

const SCALAR_TO_TS: Record<string, string> = {
  [ScalarType.String]: "string",
  [ScalarType.Int]: "number",
  [ScalarType.Float]: "number",
  [ScalarType.Boolean]: "boolean",
  [ScalarType.DateTime]: "Date",
  [ScalarType.Json]: "unknown",
  [ScalarType.BigInt]: "bigint",
  [ScalarType.Bytes]: "Buffer",
  [ScalarType.Decimal]: "string",
};

// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * Generates TypeScript client code from an IndigoDB Schema AST.
 *
 * @param schema - The parsed schema AST.
 * @param options - Generator options.
 * @returns Generated TypeScript source code as a string.
 *
 * @example
 * ```ts
 * import { parse } from "@indigodb/parser";
 * import { generate } from "@indigodb/generator";
 *
 * const schema = parse(fs.readFileSync("schema.indigo", "utf-8"));
 * const code = generate(schema);
 * fs.writeFileSync("generated/client.ts", code);
 * ```
 */
export function generate(
  schema: Schema,
  options: GeneratorOptions = {},
): string {
  const lines: string[] = [
    "// ──────────────────────────────────────────────────────────────────────────────",
    "// Auto-generated by IndigoDB Generator — DO NOT EDIT",
    `// Generated at: ${new Date().toISOString()}`,
    "// ──────────────────────────────────────────────────────────────────────────────",
    "",
  ];

  // Generate enum types
  for (const enumDef of schema.enums) {
    lines.push(`export enum ${enumDef.name} {`);
    for (const value of enumDef.values) {
      lines.push(`  ${value.name} = "${value.name}",`);
    }
    lines.push(`}`);
    lines.push("");
  }

  // Generate model interfaces
  for (const model of schema.models) {
    lines.push(...generateModelInterface(model, schema));
    lines.push("");
  }

  return lines.join("\n");
}

// ─── Internal Helpers ────────────────────────────────────────────────────────

function generateModelInterface(model: Model, schema: Schema): string[] {
  const lines: string[] = [];

  lines.push(`export interface ${model.name} {`);

  for (const field of model.fields) {
    const tsType = mapFieldToTS(field, schema);
    const optional = field.type.optional ? "?" : "";
    lines.push(`  ${field.name}${optional}: ${tsType};`);
  }

  lines.push(`}`);

  return lines;
}

function mapFieldToTS(field: Field, schema: Schema): string {
  const { type } = field;
  let tsType = mapTypeNameToTS(type, schema);

  if (type.list) {
    tsType = `${tsType}[]`;
  }

  if (type.optional) {
    tsType = `${tsType} | null`;
  }

  return tsType;
}

function mapTypeNameToTS(type: FieldType, schema: Schema): string {
  // Check scalar types first
  if (SCALAR_TO_TS[type.name]) {
    return SCALAR_TO_TS[type.name];
  }

  // Check if it's an enum
  const isEnum = schema.enums.some((e) => e.name === type.name);
  if (isEnum) {
    return type.name;
  }

  // Check if it's a model (relation)
  const isModel = schema.models.some((m) => m.name === type.name);
  if (isModel) {
    return type.name;
  }

  // Fallback to unknown
  return "unknown";
}
